using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.ProbabilisticClosure.TrajectoryLaws;
internal sealed class NativeBorelTVTopologyDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Observer/ProbabilisticClosure/TrajectoryLaws/NativeBorelTVTopology.";
    public DocumentDefinition Create()
    {
        Formula s=F.Id("s");
        return DocumentDefinition.Create(ScribeNode.Create("Total variation and complete coordinates", H("Borel law transport"), Blocks(
            Paragraph(Text("For each active phase, the carrier is the entire probability-law space on ValidTail(s). The distance is the supremum over all measurable events of the maximum of the two directed ENNReal gaps. tvTopology is the topology generated by this distance, and coordinateTopology is induced by the complete singleton-coordinate equivalence into Simplex(s). Infinity belongs to the carrier and the coordinate map.")),
            Node("tv_topology_eq_coordinates",All(Eqn(Call("tvTopology",s),Call("coordinateTopology",s)),("s","ActivePhase")),"Every singleton real mass is Lipschitz with constant one for the actual TV distance. ENNReal singleton mass is the continuous ofReal image of that real mass. Conversely, arbitrary probability laws admit finite sets with arbitrarily small complementary mass. The finite sum of coordinate discrepancies tends to zero in the coordinate topology. The event-supremum finite-coordinate estimate then places a coordinate neighborhood inside every TV ball. These two directions identify the topologies for all laws, including laws of infinite support."),
            Node("tv_borel_eq",All(Eqn(Call("Borel",Call("tvTopology",s)),Call("Giry",Call("ProbabilityMeasure",Call("ValidTail",s)))),("s","ActivePhase")),"The complete-coordinate map is a measurable equivalence, and its target simplex has the inherited Borel structure of a countable ENNReal product. The established topology equality therefore identifies actual TV-Borel with the evaluation/Giry sigma algebra. No weak-convergence topology is substituted."),
            Node("descriptor_tv_borel_eq",All(Eqn(Call("Borel",Call("descriptorTVTopology",s)),Call("InheritedGiry",Call("RegularDescriptor",s))),("s","ActivePhase")),"descriptorTVTopology is the exact subspace TV topology on the unchanged Regular predicate. Subspace Borel transport gives its inherited measurable structure. Both phase marginals, the acquired kernels, full residuals and bounded real input tests can consequently use this same measurable carrier. The two full joint-test equivalences apply this identification to their original fixed joint laws and unweighted margins."))));
    }
    private static DocumentBlock.Describe Node(string declaration, Formula formula, string prose,
        DescribeRole role = DescribeRole.Theorem) => Describe.Lean(
        DescribeId.Create(declaration.Replace('_','-').ToLowerInvariant()), DeclarationHandle.Create(Prefix+declaration),
        H(declaration.Replace('_',' ')), StatementSource.FromAuthor(Disp(formula)),
        AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
    private static Formula Eqn(Formula a, Formula b) => Seq(a, Eq, b);
    private static Formula All(Formula body, params (string Name,string Type)[] xs) {
        for(int k=xs.Length-1;k>=0;k--) body=Seq(Forall,Sp,F.Id(xs[k].Name),Colon,Sp,F.Id(xs[k].Type),Comma,Sp,body);
        return body;
    }
}
